export function buildConceptMap(): Map<string, VerseConcept[]> {
  const map = new Map<string, VerseConcept[]>();
  for (const vc of VERSE_CONCEPTS) {
    if (!map.has(vc.verseId)) map.set(vc.verseId, []);
    map.get(vc.verseId)!.push(vc);
  }
  return map;
}
